    if not s:
        raise ValueError("Invalid duration string")

    total_seconds = 0
    pattern = ""

    while s:
        if s[0].isdigit():
            pattern += s[0]
        elif s[0] in ('h', 'm', 's'):
            if not pattern:
                raise ValueError("Invalid duration string")
            value = int(pattern)
            unit = s[0]

            if unit == 'h':
                total_seconds += value * 3600
            elif unit == 'm':
                total_seconds += value * 60
            elif unit == 's':
                total_seconds += value

            s = s[1:]
            pattern = ""
        else:
            raise ValueError("Invalid duration string")

    if pattern:
        raise ValueError("Invalid duration string")

    return total_seconds
