def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluates each item (files and directories) in a given directory against specified conditions.

    Parameters:
    dir_path (str): Path to the directory to evaluate
    predicates (list): List of strings representing conditions to check

    Returns:
    dict: A dictionary with directory items as keys and the results of condition checks as values

    Raises:
    ValueError: If no valid predicates are provided
    FileNotFoundError: If the specified directory does not exist or is not a directory
    """
    # Check if directory exists and is a directory
    if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
        raise FileNotFoundError(f"The directory {dir_path} does not exist or is not a directory")

    # Process and validate predicates
    valid_predicates = []
    for pred in predicates:
        if not isinstance(pred, str) or not pred.strip():
            continue

        # Remove duplicates while preserving order
        if pred not in valid_predicates:
            valid_predicates.append(pred)

    if not valid_predicates:
        raise ValueError("No valid predicates are provided")

    # Create a function to evaluate each predicate
    def evaluate_item(item_name: str, pred: str) -> bool:
        """Evaluate a single item against a predicate"""
        pred = pred.strip()

        # Try to parse the predicate
        # Format: "name:pattern" for regex matching
        # Format: "name:substring" for substring matching
        # Format: "name" for exact match
        if ':' in pred:
            parts = pred.split(':', 1)
            if len(parts) == 2:
                condition_type, pattern = parts
                condition_type = condition_type.strip()
                pattern = pattern.strip()

                if condition_type == 'name':
                    try:
                        return bool(re.fullmatch(pattern, item_name))
                    except re.error:
                        # If regex fails, try as substring
                        return pattern in item_name
                elif condition_type == 'contains':
                    return pattern in item_name
                elif condition_type == 'startswith':
                    return item_name.startswith(pattern)
                elif condition_type == 'endswith':
                    return item_name.endswith(pattern)

        # Default to exact match
        return item_name == pred

    # Evaluate each item in the directory
    result = {}
    for item_name in os.listdir(dir_path):
        item_path = os.path.join(dir_path, item_name)
        if os.path.isfile(item_path):
            # For files, we only check the filename
            evaluation = {pred: evaluate_item(item_name, pred) for pred in valid_predicates}
            result[item_name] = evaluation
        else:
            # For directories, we only check the directory name
            evaluation = {pred: evaluate_item(item_name, pred) for pred in valid_predicates}
            result[item_name] = evaluation

    return result
